// Some portions generated by Claude
// The organic engine's parts: size-aware stress, core/pendant decomposition, fans, the port-aware router and packing.
import assert from 'node:assert/strict';
import test from 'node:test';
import { stressLayout } from '../../../main/frontend/graph-explorer/graph-layout-stress.ts';
import { decomposeComponent, componentsOf } from '../../../main/frontend/graph-explorer/graph-layout-structure.ts';
import { placeFan, unitShapes } from '../../../main/frontend/graph-explorer/graph-layout-fans.ts';
import { routeEdges } from '../../../main/frontend/graph-explorer/graph-edge-router.ts';
import { packComponents } from '../../../main/frontend/graph-explorer/graph-layout-packing.ts';
import { computeGraphLayout } from '../../../main/frontend/graph-explorer/graph-layout-engine.ts';
import { graphNodeSize } from '../../../main/frontend/graph-explorer/graph-geometry.ts';
import { expansionMovableIds } from '../../../main/frontend/graph-explorer/graph-layout-expansion.ts';
import { seedIncrementalNodes } from '../../../main/frontend/graph-explorer/graph-operations.ts';
import { RDF_TYPE } from '../../../main/frontend/graph-explorer/graph-canvas-scope.ts';
import { hashHub } from './fixtures/layout-hash-hub.mjs';
import { layoutMetrics } from './support/benchmark-layout.mjs';

const half = (values) => Float64Array.from(values, (value) => value / 2);
function cards(widths, heights) {
  return { left: half(widths), right: half(widths), top: half(heights), bottom: half(heights) };
}

test('stress draws a path straight, with an arrow length between the cards, and is deterministic', () => {
  const n = 6, widths = new Array(n).fill(200), heights = new Array(n).fill(46);
  const links = Int32Array.from(Array.from({ length: n - 1 }, (_, i) => [i, i + 1]).flat());
  const run = () => {
    const problem = { ...cards(widths, heights), x: new Float64Array(n), y: new Float64Array(n), links };
    stressLayout(problem, { edgeLength: 90 });
    return problem;
  };
  const first = run(), second = run();
  assert.deepEqual([...first.x], [...second.x]);
  // Straight: every card on the line through the two ends.
  const dx = first.x[n - 1] - first.x[0], dy = first.y[n - 1] - first.y[0], length = Math.hypot(dx, dy);
  for (let i = 1; i < n - 1; i++) {
    const off = Math.abs((first.x[i] - first.x[0]) * dy - (first.y[i] - first.y[0]) * dx) / length;
    assert.ok(off < 12, `card ${i} is ${off.toFixed(1)} px off the line`);
  }
  // The gap between neighbouring cards along the line is about one arrow length.
  for (let i = 1; i < n; i++) {
    const ux = Math.abs(dx / length), uy = Math.abs(dy / length);
    const border = Math.min(100 / Math.max(ux, 1e-9), 23 / Math.max(uy, 1e-9));
    const gap = Math.hypot(first.x[i] - first.x[i - 1], first.y[i] - first.y[i - 1]) - 2 * border;
    assert.ok(gap > 60 && gap < 130, `gap ${gap.toFixed(0)} between cards ${i - 1} and ${i}`);
  }
});

test('stress keeps fixed cards where they are and leaves no two cards overlapping', () => {
  const n = 12, widths = new Array(n).fill(180), heights = new Array(n).fill(46);
  // A star: every card linked to card 0, which is pinned at (500, 300).
  const links = Int32Array.from(Array.from({ length: n - 1 }, (_, i) => [0, i + 1]).flat());
  const x = new Float64Array(n), y = new Float64Array(n), fixed = new Uint8Array(n);
  x[0] = 500; y[0] = 300; fixed[0] = 1;
  const problem = { ...cards(widths, heights), x, y, links, fixed };
  stressLayout(problem, { edgeLength: 90, initialize: true });
  assert.deepEqual([problem.x[0], problem.y[0]], [500, 300]);
  for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) {
    const clear = Math.abs(problem.x[i] - problem.x[j]) >= 180 || Math.abs(problem.y[i] - problem.y[j]) >= 46;
    assert.ok(clear, `cards ${i} and ${j} overlap`);
  }
});

test('a tree is drawn around its centroid; pendant trees hang off the 2-core', () => {
  // Hub 0 with leaves 1..5 and a chain 0-6-7-8: the hub is the centroid although card 6 has the smallest eccentricity.
  const neighbors = [[1, 2, 3, 4, 5, 6], [0], [0], [0], [0], [0], [0, 7], [6, 8], [7]];
  const tree = decomposeComponent(neighbors, neighbors.map((_, i) => i));
  assert.ok(tree.tree);
  assert.deepEqual(tree.core, [0]);
  assert.deepEqual(tree.children[0], [1, 2, 3, 4, 5, 6]);
  assert.deepEqual(tree.children[6], [7]);
  // A triangle 0-1-2 with a leaf 3 on 0 and a chain 4-5 on 2.
  const cyclic = [[1, 2, 3], [0, 2], [0, 1, 4], [0], [2, 5], [4]];
  const core = decomposeComponent(cyclic, cyclic.map((_, i) => i));
  assert.ok(!core.tree);
  assert.deepEqual(core.core.sort(), [0, 1, 2]);
  assert.equal(core.parent[3], 0);
  assert.equal(core.parent[5], 4);
  assert.deepEqual(componentsOf([[1], [0], [], [4], [3]]), [[0, 1], [2], [3, 4]]);
});

test('a big fan stands outside its inner rectangle, so every arrow to the inner side of a unit stays clear', () => {
  const size = () => ({ width: 220, height: 46 });
  const children = [Array.from({ length: 28 }, (_, i) => i + 1), ...Array.from({ length: 28 }, () => [])];
  const shape = unitShapes(children, size, { edgeLength: 90, clearX: 48, clearY: 36, aspectRatio: 1.6 });
  const fan = placeFan({ halfWidth: 110, halfHeight: 23, units: children[0], shape, spacing: { edgeLength: 90, clearX: 48, clearY: 36, aspectRatio: 1.6 }, spread: true });
  assert.equal(fan.placements.length, 28);
  const { hx, hy } = fan.inner;
  const boxes = fan.placements.map((p) => ({ minX: p.x - 110, maxX: p.x + 110, minY: p.y - 23, maxY: p.y + 23 }));
  for (const box of boxes) assert.ok(box.minX >= hx - 0.5 || box.maxX <= -hx + 0.5 || box.minY >= hy - 0.5 || box.maxY <= -hy + 0.5, 'a unit lies inside the ring');
  for (let i = 0; i < boxes.length; i++) for (let j = i + 1; j < boxes.length; j++) {
    const a = boxes[i], b = boxes[j];
    assert.ok(a.minX >= b.maxX + 47.5 || b.minX >= a.maxX + 47.5 || a.minY >= b.maxY + 35.5 || b.minY >= a.maxY + 35.5, `units ${i} and ${j} are too close`);
  }
  // A small fan of leaves is an ellipse around its anchor instead: every leaf at a similar distance.
  const small = placeFan({ halfWidth: 110, halfHeight: 23, units: [1, 2, 3, 4, 5], shape, spacing: { edgeLength: 90, clearX: 48, clearY: 36, aspectRatio: 1.6 }, spread: true });
  const radii = small.placements.map((p) => Math.hypot(p.x, p.y));
  assert.ok(Math.max(...radii) <= 1.5 * Math.min(...radii), `radii ${radii.map((r) => r.toFixed(0))}`);
});

test('the router moves an arrow\'s ends before it detours, keeps parallel lanes and leaves clear arrows alone', () => {
  const node = (id, x, y, label = 'A card with a long label') => ({ id, label, kind: 'iri', x, y });
  const edge = (id, source, target) => ({ id, source, target, predicate: 'urn:p', label: 'p' });
  // A column of cards beside a hub: the arrow aimed at the top card's centre would cut the card below it.
  const nodes = [node('hub', 0, 0), node('top', 400, -170), node('below', 400, -105), node('far', 1200, 0), node('mid', 600, 0)];
  const edges = [edge('to-top', 'hub', 'top'), edge('to-below', 'hub', 'below'), edge('p1', 'top', 'far'), edge('p2', 'top', 'far'), edge('blocked', 'hub', 'far')];
  const { bends, routes } = routeEdges(nodes, edges);
  assert.ok(routes.has('to-top'), 'the steep arrow gets new ends');
  assert.equal(routes.get('to-top').points.length, 2, 'a straight line between other ends, not a detour');
  assert.ok(!routes.has('to-below') || routes.get('to-below').points.length === 2);
  assert.notEqual(bends.get('p1'), bends.get('p2'), 'parallel arrows keep separate lanes');
  assert.ok(routes.get('blocked').points.length > 2, 'an arrow through a card in line detours round it');
  const size = graphNodeSize(nodes[4]);
  assert.ok(routes.get('blocked').points.every((p) => Math.abs(p.x - 600) > size.width / 2 || Math.abs(p.y) > size.height / 2));
});

test('packing puts small components into the corners a large one leaves empty', () => {
  // An L-shaped component (two arms) and a small one that fits into its empty corner.
  const box = (x, y) => ({ minX: x - 100, maxX: x + 100, minY: y - 23, maxY: y + 23 });
  const large = { boxes: [box(0, 0), box(0, 300), box(0, 600), box(400, 600), box(800, 600)], segments: [[0, 0, 0, 600], [0, 600, 800, 600]] };
  const small = { boxes: [box(0, 0), box(0, 100)], segments: [[0, 0, 0, 100]] };
  const offsets = packComponents([large, small], 1.6, 48);
  const placed = small.boxes.map((b) => ({ minX: b.minX + offsets[1].x - offsets[0].x, maxX: b.maxX + offsets[1].x - offsets[0].x,
    minY: b.minY + offsets[1].y - offsets[0].y, maxY: b.maxY + offsets[1].y - offsets[0].y }));
  for (const a of placed) for (const b of large.boxes) assert.ok(a.minX >= b.maxX || b.minX >= a.maxX || a.minY >= b.maxY || b.minY >= a.maxY, 'components overlap');
  const right = Math.max(...placed.map((b) => b.maxX)), bottom = Math.max(...placed.map((b) => b.maxY));
  assert.ok(right <= 900 && bottom <= 623, 'the small component sits within the large one\'s box');
});

test('organize draws an expanded hub as a compact fan: no overlap, crossing or arrow through a card', async () => {
  const graph = hashHub();
  const result = await computeGraphLayout(graph, { mode: 'network', aspectRatio: 1.6 });
  const metrics = layoutMetrics(graph, result.positions, result.bends, result.routes);
  assert.equal(metrics.nodeOverlaps, 0);
  assert.equal(metrics.edgeCrossings, 0);
  assert.equal(metrics.routedEdgeNodeOverlaps, 0);
  // The two separate pairs sit a component gap from the fan (2.66M; 1.96M when components were packed a card gap apart).
  assert.ok(metrics.area < 2.8e6, `area ${(metrics.area / 1e6).toFixed(2)}M px²`);
  const curved = [...result.routes.values()].filter((route) => route.points.length > 2);
  assert.equal(curved.length, 0, 'every arrow is straight');
});

test('expanding a hub fans its new leaves around it and leaves cards that may not move in place', async () => {
  const graph = hashHub();
  const hub = graph.nodes[0].id, fresh = new Set(graph.edges.filter((e) => e.source === hub).map((e) => e.target).slice(0, 28));
  const before = { ...graph, nodes: graph.nodes.filter((n) => !fresh.has(n.id)), edges: graph.edges.filter((e) => !fresh.has(e.target)) };
  const first = await computeGraphLayout(before, { mode: 'network', aspectRatio: 1.6 });
  const placed = new Map(first.positions);
  const anchor = placed.get(hub);
  const nodes = graph.nodes.map((n) => ({ ...n, ...(placed.get(n.id) ?? { x: anchor.x + 10, y: anchor.y + 10 }) }));
  // As the app does: the new cards, the hub, the cards within two links of it and the cards near it may move.
  const movable = new Set([hub, ...fresh]);
  for (let hop = 0; hop < 2; hop++) for (const e of graph.edges) {
    if (movable.has(e.source)) movable.add(e.target); else if (movable.has(e.target)) movable.add(e.source);
  }
  for (const n of nodes) if (Math.hypot(n.x - anchor.x, n.y - anchor.y) <= 600) movable.add(n.id);
  const result = await computeGraphLayout({ ...graph, nodes }, { mode: 'network', aspectRatio: 1.6, incremental: true, movableNodeIds: movable, newNodeIds: fresh });
  for (const n of nodes) if (!movable.has(n.id)) assert.deepEqual(result.positions.get(n.id), { x: n.x, y: n.y }, `${n.label} moved`);
  const metrics = layoutMetrics({ ...graph, nodes }, result.positions, result.bends, result.routes);
  assert.equal(metrics.nodeOverlaps, 0);
  assert.equal(metrics.routedEdgeNodeOverlaps, 0);
  assert.equal(metrics.edgeCrossings, 0);
  const center = result.positions.get(hub);
  const spokes = [...fresh].map((id) => Math.hypot(result.positions.get(id).x - center.x, result.positions.get(id).y - center.y));
  assert.ok(Math.max(...spokes) < 1000, `longest new spoke ${Math.max(...spokes).toFixed(0)} px`);
  assert.ok(Math.hypot(center.x - anchor.x, center.y - anchor.y) < 900, 'the hub stays near where it was');
});

test('showing values places them beside their cards and a class card among its instances; nothing else moves', async () => {
  // As the Values button does: a layout of the value and class cards only (no layout mode asked for).
  const people = Array.from({ length: 7 }, (_, i) => ({ id: `urn:p${i}`, label: `Person ${i + 1}`, kind: 'iri' }));
  const ages = people.map((_, i) => ({ id: `"${20 + i}"`, label: String(20 + i), kind: 'literal' }));
  const human = { id: 'urn:Person', label: 'Human', kind: 'iri' };
  const knows = people.slice(1).map((p, i) => ({ id: `k${i}`, source: p.id, target: people[i].id, predicate: 'urn:knows', label: 'knows' }));
  const first = await computeGraphLayout({ nodes: people, edges: knows, revision: 1 }, { mode: 'network', aspectRatio: 1.6 });
  const placed = people.map((p) => ({ ...p, ...first.positions.get(p.id) }));
  const edges = [...knows,
    ...people.map((p, i) => ({ id: `a${i}`, source: p.id, target: ages[i].id, predicate: 'urn:age', label: 'age' })),
    ...people.map((p, i) => ({ id: `t${i}`, source: p.id, target: human.id, predicate: RDF_TYPE, label: 'type' }))];
  const graph = { nodes: [...placed, ...ages, human], edges, revision: 2 };
  const result = await computeGraphLayout(graph, { aspectRatio: 1.6, localNodeIds: new Set([...ages.map((a) => a.id), human.id]) });
  for (const p of placed) assert.deepEqual(result.positions.get(p.id), { x: p.x, y: p.y }, `${p.label} moved`);
  people.forEach((p, i) => {
    const a = result.positions.get(ages[i].id), q = result.positions.get(p.id);
    assert.ok(Math.hypot(a.x - q.x, a.y - q.y) < 260, `the value of ${p.label} is ${Math.round(Math.hypot(a.x - q.x, a.y - q.y))} px from it`);
  });
  const xs = placed.map((p) => p.x), ys = placed.map((p) => p.y), h = result.positions.get(human.id);
  assert.ok(h.x > Math.min(...xs) && h.x < Math.max(...xs) && h.y > Math.min(...ys) - 200 && h.y < Math.max(...ys) + 200,
    `the class card stands at ${Math.round(h.x)},${Math.round(h.y)}, away from its instances`);
  assert.equal(layoutMetrics(graph, result.positions, result.bends, result.routes).nodeOverlaps, 0);
});

test('the new cards of an expansion do not use up what the drawn cards near it may move', () => {
  // A card with 30 new neighbours, drawn beside eight unrelated cards: the drawn cards near it may give way.
  const nodes = [{ id: 'hub', x: 0, y: 0 }];
  const edges = [];
  for (let i = 0; i < 30; i++) { nodes.push({ id: `new${i}` }); edges.push({ source: 'hub', target: `new${i}` }); }
  for (let i = 0; i < 8; i++) nodes.push({ id: `old${i}`, x: 300 + 40 * i, y: 100 });
  const movable = expansionMovableIds(nodes, edges, 'hub', new Set(nodes.filter((n) => n.id.startsWith('new')).map((n) => n.id)));
  for (let i = 0; i < 8; i++) assert.ok(movable.has(`old${i}`), `old${i} may not move`);
});

test('expanding a card two links from a drawn hub leaves the hub and its fan in place', async () => {
  // As in the app: load one link of the hub, then double-click the hub, the chain card below it and the next one.
  // The last expansion may move the hub (two links away) but not most of its leaves; the hub must not leave them.
  const full = hashHub();
  const hub = full.nodes[0].id, [a, b, c] = full.nodes.slice(29, 32).map((n) => n.id);
  const shown = new Set([hub, full.nodes[1].id]);
  const subgraph = (ids, placed) => ({
    nodes: full.nodes.filter((n) => ids.has(n.id)).map((n) => ({ ...n, ...placed?.get(n.id) })),
    edges: full.edges.filter((e) => ids.has(e.source) && ids.has(e.target)),
    revision: ids.size,
  });
  let positions = (await computeGraphLayout(subgraph(shown), { mode: 'network', aspectRatio: 1.6 })).positions;
  const expand = async (anchorId) => {
    const previous = new Set(shown);
    for (const e of full.edges) {
      if (e.source === anchorId) shown.add(e.target);
      if (e.target === anchorId) shown.add(e.source);
    }
    const seeded = seedIncrementalNodes(subgraph(shown, positions), previous, [anchorId]);
    const fresh = new Set([...shown].filter((id) => !previous.has(id)));
    const movable = expansionMovableIds(seeded.nodes, seeded.edges, anchorId, fresh);
    const result = await computeGraphLayout(seeded, { mode: 'network', aspectRatio: 1.6, incremental: true, movableNodeIds: movable, newNodeIds: fresh });
    return { seeded, result };
  };
  positions = (await expand(hub)).result.positions;
  positions = (await expand(a)).result.positions;
  const before = positions;
  const { seeded, result } = await expand(b);
  const moved = (id) => Math.hypot(result.positions.get(id).x - before.get(id).x, result.positions.get(id).y - before.get(id).y);
  assert.ok(moved(hub) < 1, `the hub moved ${moved(hub).toFixed(0)} px`);
  const leaves = full.edges.filter((e) => e.source === hub && e.target !== a).map((e) => e.target);
  for (const leaf of leaves) assert.ok(moved(leaf) < 1, `a leaf of the hub moved ${moved(leaf).toFixed(0)} px`);
  const gap = Math.hypot(result.positions.get(c).x - result.positions.get(b).x, result.positions.get(c).y - result.positions.get(b).y);
  assert.ok(gap < 450, `the new card is ${gap.toFixed(0)} px from the card it was expanded from`);
  const metrics = layoutMetrics(seeded, result.positions, result.bends, result.routes);
  assert.equal(metrics.nodeOverlaps, 0);
  assert.equal(metrics.edgeCrossings, 0);
  assert.equal(metrics.routedEdgeNodeOverlaps, 0);
});
